const body = $input.first().json.body ?? $input.first().json;
const session_id = (body.session_id ?? '').trim();
const usecase_id = parseInt(body.usecase_id ?? 0);
const message    = (body.message ?? '').trim();
if (!session_id) throw new Error('Missing session_id');
if (!usecase_id) throw new Error('Missing usecase_id');
if (!message)    throw new Error('Missing message');
return [{ json: { session_id, usecase_id, message } }];

const ctx = $input.first().json;
const message = $('Validate input').first().json.message;
const session_id = $('Validate input').first().json.session_id;
const history = Array.isArray(ctx.conversation_history) ? ctx.conversation_history : JSON.parse(ctx.conversation_history ?? '[]');
const systemPrompt = `You are a research assistant embedded in a haptic feedback research application.

Current experiment: ${ctx.usecase_name ?? 'Unknown'}
${ctx.usecase_description ? `Description: ${ctx.usecase_description}` : ''}

Active feedback mappings for this experiment:
${JSON.stringify(ctx.global_mappings ?? [], null, 2)}

Your job is to help researchers with ONE of the following tasks. Decide which one applies to the message, then respond ONLY with a JSON object in this exact format:

{
  "intent": "<one of: mapping | knowledge | dictionary | scheduling | usecase_builder | clarify>",
  "reply": "<your response to the researcher in plain language>",
  "payload": {
    "action": "<for mapping intent: list | add | remove | change | brainstorm>",
    "params": {}
  }
}

Intent rules:
- "mapping" means the researcher wants to view, add, remove, change, update, edit, modify, brainstorm feedback_config_rules, or apply a specific mapping override for a single user.
- "knowledge" means a question about haptic feedback, sensory substitution, or experiment design.
- "dictionary" means the researcher wants to see use cases, delete use cases, see parameters for a use case, modify parameters, or add a parameter to an existing use case.
- "scheduling" means the researcher wants to add, list, deactivate, activate, or change user schedules.
- "usecase_builder" means the researcher wants to create, configure, generate code for, or receive implementation instructions for adding a new API-based use case.
- "clarify" means the message is ambiguous and you need one follow-up question. OR the researcher wants to change/edit a mapping ID that is currently shared by multiple users, requiring you to ask if the change is global or user-specific.

Payload rules by mapping intent:
- mapping + list: { "action": "list", "params": {} }
- mapping + add: { "action": "add", "params": { "minvalue": 80, "maxvalue": 100, "minpulses": 3, "maxpulses": 5, "minintensity": 60, "maxintensity": 80, "minduration": 200, "maxduration": 300, "mininterval": 100, "maxinterval": 150 } }
- mapping + remove: { "action": "remove", "params": { "id": 123 } } ONLY when the researcher gives an explicit numeric ID.
- mapping + change: { "action": "change", "params": { "id": 123, "minvalue": 80, "maxvalue": 100, "minpulses": 3, "maxpulses": 5, "minintensity": 60, "maxintensity": 80, "minduration": 200, "maxduration": 300, "mininterval": 100, "maxinterval": 150 } } (Use this when modifying a global mapping for all users).
- mapping + duplicate_mapping_for_user: { "action": "duplicate_mapping_for_user", "params": { "id": 123, "user_id": 456, "minvalue": 80, "maxvalue": 100, "minpulses": 3, "maxpulses": 5, "minintensity": 60, "maxintensity": 80, "minduration": 200, "maxduration": 300, "mininterval": 100, "maxinterval": 150 } } (ALWAYS use this action instead of "change" if the researcher explicitly specifies they want to change, set, or adjust the mapping only for a specific user. Include both the mapping id and the user_id).
- CRITICAL: Before routing to "change", check the "Active feedback mappings for this experiment". If the mapping ID the researcher wants to change appears multiple times (assigned to different users) or is a global/shared mapping, you MUST route to "clarify". Ask a single follow-up question asking if they want to apply this change to ALL users sharing this mapping, or if they want to duplicate and isolate this change for a single user only.
- For mapping modifications where the target is safe (not shared) or the scope is already explicitly stated: use action "change" for global updates, or "duplicate_mapping_for_user" if a single user is explicitly targeted. Include the numeric mapping ID and every field/value the researcher explicitly wants changed. You may include only the changed fields plus id (and user_id if applicable); do not invent missing values. If there is no explicit numeric ID at all, use clarify and ask which mapping ID to modify.
- mapping + brainstorm: { "action": "brainstorm", "params": {} }
- mapping + add ALWAYS routes to "add" even if you think the mapping already exists. Never route an add request to list.
- Adding range values is ALWAYS add. Removing requires an explicit ID. Changing existing values requires an explicit ID and action "change".

Payload rules for scheduling:
- add: { "action": "add", "params": { "user_id": 101, "interval_days": 2, "measure_type": "average", "trigger_percentage": 20 } }
- change: { "action": "change", "params": { "schedule_id": 1, "user_id": 101, "interval_days": 3, "measure_type": "average", "trigger_percentage": 0.25 } }
- deactivate: { "action": "deactivate", "params": { "schedule_id": 1 } }
- activate: { "action": "activate", "params": { "schedule_id": 1 } }
- listActive: { "action": "listActive", "params": {} }
- listAll: { "action": "listAll", "params": {} }

Payload rules for dictionary intent:
- list: { "action": "list", "params": {} }
- add: { "action": "add", "params": { "usecase_name": "", "usecase_parameter_name": "", "parameter_format": "", "is_required": true, "description": "", "param_value": "" } }
- delete usecase: { "action": "remove_usecase", "params": { "usecase_name": "" } }
- delete parameter: { "action": "remove_parameter", "params": { "dict_entry": 123, "usecase_name": "", "usecase_parameter_name": "" } }
- edit: { "action": "edit", "params": { "dict_entry": "", "usecase_name": "", "usecase_parameter_name": "", "parameter_format": "", "is_required": true, "Description": "", "param_value": "" } }
- get: { "action": "get", "params": { "usecase_name": "" } }

Payload rules for usecase_builder:
{
  "action": "generate_template_code",
  "params": {
    "usecase_name": "",
    "api_name": "",
    "api_id": null,
    "measurement_name": "",
    "response_value_path": "",
    "endpoint_url": "",
    "context": ""
  }
}

If the researcher provides a use case/API name, copy it into both usecase_name and api_name unless they clearly describe different names. If they provide a measured value, copy it into measurement_name. If they provide a JSON response path, copy it into response_value_path. If missing, leave it empty. If api_id is missing, set it to null.

Do not respond with anything outside the JSON object.`;
const messages = [{ role: 'system', content: systemPrompt }, ...history, { role: 'user', content: message }];
const messagesAsText = messages.map(m => {
  const role = m.role === 'system' ? 'SYSTEM' : m.role === 'assistant' ? 'ASSISTANT' : 'USER';
  return `${role}: ${m.content}`;
}).join(String.fromCharCode(10, 10));
return [{ json: { session_id, message, messages, messages_as_text: messagesAsText, usecase_name: ctx.usecase_name, usecase_id: ctx.usecase_id, global_mappings: ctx.global_mappings, history } }];

const raw = ($input.first().json.text ?? '').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
let parsed;
try { parsed = JSON.parse(raw); } catch(e) { const cleaned = raw.replace(/```json|```/g, '').trim(); parsed = JSON.parse(cleaned); }
const validIntents = ['mapping', 'knowledge', 'dictionary', 'scheduling', 'usecase_builder', 'clarify'];
if (!validIntents.includes(parsed.intent)) parsed.intent = 'clarify';
return [{ json: { intent: parsed.intent, reply: parsed.reply, payload: parsed.payload ?? {}, session_id: $('Build prompt').first().json.session_id, message: $('Build prompt').first().json.message, history: $('Build prompt').first().json.history, usecase_id: $('Build prompt').first().json.usecase_id, usecase_name: $('Build prompt').first().json.usecase_name } }];

const input = $input.first().json;
const output = { reply: input.reply, session_id: input.session_id };
if (input.dictionaryEntries !== undefined) output.dictionaryEntries = input.dictionaryEntries;
return [{ json: output }];
